from __future__ import annotations

from typing_extensions import TypedDict

from ..core import SdkBaseModel
from .enums.embed4 import Embed4OrStr
from .enums.view7 import View7OrStr


class StreamPrivacy(SdkBaseModel):
    """The initial privacy settings of videos generated by streaming to the event as well as the embed privacy of the
    entire collection."""

    embed: Embed4OrStr
    """The event's embed permission setting.

    Option descriptions:
     * ``private`` - The event can't be embedded on any domain.
     * ``public`` - The event can be embedded on any domain.
     * ``whitelist`` - The event can be embedded on permitted domains only."""

    unlisted_hash: str | None
    """The hash for unlisted events."""

    view: View7OrStr
    """The general privacy setting for generated videos and the embed privacy of the entire collection.

    Option descriptions:
     * ``anybody`` - Anyone can access the videos. This privacy setting appears as ``Public`` on the Vimeo front end.
     * ``embed_only`` - The videos don't appear on Vimeo, but they can be embedded elsewhere.
     * ``nobody`` - Only the event owner can access the videos. This privacy setting appears as ``Private`` on the Vimeo
            front end.
     * ``password`` - Only those with the password can access the videos.
     * ``team`` - Anyone on this team can access the videos. This privacy setting appears as ``Company only`` on the
            Vimeo front end.
     * ``unlisted`` - Only those with the private link can access the videos."""


class StreamPrivacyDict(TypedDict):
    embed: Embed4OrStr
    unlisted_hash: str | None
    view: View7OrStr
